// Prepare the post data for approval
const nextPost = $input.first().json.nextPost;

if (!nextPost) {
  return [{ json: { skip: true, reason: 'No posts available' } }];
}

// Build the full caption with hashtags in first comment strategy
const fullCaption = nextPost.caption;
const hashtags = nextPost.hashtags;

// Construct the publicly accessible image URL
// Images should be hosted on Vercel Blob or similar CDN
const imageUrl = nextPost.image.startsWith('http')
  ? nextPost.image
  : `${$env.SITE_URL}/content/portfolio/${nextPost.image}`;

return [{
  json: {
    postId: nextPost.id,
    title: nextPost.title,
    pillar: nextPost.pillar,
    style: nextPost.style,
    animal: nextPost.animal,
    caption: fullCaption,
    hashtags: hashtags,
    imageUrl: imageUrl,
    image: nextPost.image,
    date: new Date().toISOString().split('T')[0]
  }
}];

