// Parse the GChat reply to determine the action
const webhookData = $input.first().json;

// The reply can come from:
// 1. GChat webhook response body
// 2. Manual trigger with { reply: 'yes' }
let reply = '';

if (webhookData.body?.text) {
  reply = webhookData.body.text.trim().toLowerCase();
} else if (webhookData.reply) {
  reply = webhookData.reply.trim().toLowerCase();
} else if (webhookData.text) {
  reply = webhookData.text.trim().toLowerCase();
} else {
  // Timeout - default to skip
  reply = 'timeout';
}

const postData = $('Prepare Post Data').item.json;

let action = 'skip';
let editedCaption = '';

if (reply === 'yes' || reply === 'approve' || reply === 'y') {
  action = 'approve';
} else if (reply.startsWith('edit:')) {
  action = 'edit';
  editedCaption = reply.replace(/^edit:\s*/, '');
} else if (reply === 'skip' || reply === 'no' || reply === 'n' || reply === 'timeout') {
  action = 'skip';
}

return [{
  json: {
    action,
    postId: postData.postId,
    imageUrl: postData.imageUrl,
    caption: postData.caption,
    hashtags: postData.hashtags,
    editedCaption: editedCaption || undefined,
    reply: reply
  }
}];

